const payload = $json.body ?? $json;
const line = payload.rfq_line ?? {};
const lineNo = line.line_no ?? null;
const code = String(line.product_code ?? '').trim();
const description = String(line.description ?? '').trim();
const unit = String(line.unit ?? '').trim();
const qtyRaw = line.qty;
const qty = typeof qtyRaw === 'number' ? qtyRaw : Number(String(qtyRaw ?? '').replace(',', ''));
const missing = [];
if (!code) missing.push('product_code');
if (!unit) missing.push('unit');
if (qtyRaw === undefined || qtyRaw === null || Number.isNaN(qty) || qty <= 0) missing.push('qty');
return [{ json: {
  line_no: lineNo,
  product_code: code,
  description,
  unit,
  qty,
  missing_fields: missing,
  needs_review: missing.length > 0,
  review_reason: missing.length ? 'missing_field:' + missing.join(',') : null
} }];

const CATALOGUE = [
  {product_code:'CB-16A-1P', description:'MCB 16A 1-pole type C', unit:'pcs', substitute_for:null},
  {product_code:'CB-20A-1P', description:'MCB 20A 1-pole type C', unit:'pcs', substitute_for:null},
  {product_code:'CB-32A-3P', description:'MCB 32A 3-pole type C', unit:'pcs', substitute_for:null},
  {product_code:'CTC-09A-230V', description:'Contactor 9A 230V coil', unit:'pcs', substitute_for:null},
  {product_code:'TB-2.5-GY', description:'Terminal block 2.5mm2 grey', unit:'pcs', substitute_for:null},
  {product_code:'CBL-H07VK-2.5-BK', description:'Cable H07V-K 2.5mm2 black', unit:'m', substitute_for:null},
  {product_code:'RLY-230V-2CO', description:'Interface relay 230V 2CO', unit:'pcs', substitute_for:null},
  {product_code:'LUG-2.5-M4', description:'Cable lug 2.5mm2 M4', unit:'pcs', substitute_for:null},
  {product_code:'CB-16A-1P-NEW', description:'MCB 16A 1-pole type C (rev B)', unit:'pcs', substitute_for:'CB-16A-1P-OLD'},
  {product_code:'DUP-CODE-01', description:'Duplicate catalogue entry A', unit:'pcs', substitute_for:null},
  {product_code:'DUP-CODE-01', description:'Duplicate catalogue entry B', unit:'box', substitute_for:null}
];
const PRICE_LIST = [
  {product_code:'CB-16A-1P', unit:'pcs', unit_price:1.85, currency:'EUR'},
  {product_code:'CB-20A-1P', unit:'pcs', unit_price:2.10, currency:'EUR'},
  {product_code:'CB-32A-3P', unit:'pcs', unit_price:6.40, currency:'EUR'},
  {product_code:'CTC-09A-230V', unit:'pcs', unit_price:14.20, currency:'EUR'},
  {product_code:'TB-2.5-GY', unit:'pcs', unit_price:0.09, currency:'EUR'},
  {product_code:'CBL-H07VK-2.5-BK', unit:'m', unit_price:0.62, currency:'EUR'},
  {product_code:'LUG-2.5-M4', unit:'pcs', unit_price:0.18, currency:'EUR'},
  {product_code:'CB-16A-1P-NEW', unit:'pcs', unit_price:1.95, currency:'EUR'}
];
const norm = (s) => String(s ?? '').trim().toUpperCase();
const code = norm($json.product_code);
const unit = norm($json.unit);
const reasons = [];
let matched = null;
let suggested = null;
const matches = CATALOGUE.filter(c => norm(c.product_code) === code);
if (matches.length === 1) {
  matched = matches[0];
} else if (matches.length > 1) {
  reasons.push('ambiguous_catalogue_code');
} else {
  const subs = CATALOGUE.filter(c => c.substitute_for && norm(c.substitute_for) === code);
  if (subs.length === 1) {
    reasons.push('substitution_available');
    suggested = subs[0];
  } else if (subs.length > 1) {
    reasons.push('ambiguous_substitution');
  } else {
    reasons.push('unknown_code');
  }
}
let unitPrice = null;
let currency = null;
if (matched) {
  if (norm(matched.unit) !== unit) {
    reasons.push('unit_mismatch');
  } else {
    const priceRow = PRICE_LIST.find(p => norm(p.product_code) === code && norm(p.unit) === unit);
    if (!priceRow) {
      reasons.push('unapproved_price');
    } else {
      unitPrice = priceRow.unit_price;
      currency = priceRow.currency;
    }
  }
}
return [{ json: {
  line_no: $json.line_no,
  requested_code: $json.product_code,
  qty: $json.qty,
  unit,
  reasons,
  needs_review: reasons.length > 0,
  matched_code: matched ? matched.product_code : null,
  matched_description: matched ? matched.description : null,
  suggested_code: suggested ? suggested.product_code : null,
  suggested_description: suggested ? suggested.description : null,
  unit_price: unitPrice,
  currency,
  line_total: (matched && !reasons.length) ? Math.round($json.qty * unitPrice * 100) / 100 : null
} }];
